{
  "avaliacoes": [
    {
      "id": "Eb0ac218822571b86",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em FPSO monohull com heading control ativo, thrusters mantêm o aproamento em relação ao ambiente predominante, enquanto guinchos no turret permitem ajuste de tensão e recuperação periódica das linhas para inspeção em ar.",
          "trechos": [
            "Eb0ac218822571b86:0:695"
          ],
          "condicoes": [
            "aplica-se ao arranjo descrito como Active Heading Controlled FPSO com turret e mooring winches"
          ],
          "limites": [
            "o trecho descreve funcionamento típico, não estabelece critério normativo de projeto ou operação",
            "não informa limites ambientais, envelopes operacionais nem parâmetros quantitativos de tensão"
          ]
        },
        {
          "proposicao": "Efeitos de atrito entre turret e casco podem transferir movimentos de yaw induzidos por ondas de alta frequência para o sistema de ancoragem, especialmente na região de fairleads, aumentando desgaste.",
          "trechos": [
            "Eb0ac218822571b86:695:1395"
          ],
          "condicoes": [
            "no contexto de FPSO com turret e influência de atrito relativamente elevado entre turret e embarcação"
          ],
          "limites": [
            "o texto não quantifica a severidade do desgaste nem define condições meteoceanográficas específicas",
            "a relação é explicação técnica do mecanismo, não resultado experimental generalizável"
          ]
        },
        {
          "proposicao": "Na perda de controle dos thrusters, o vento pode desviar o aproamento, levando ao enrolamento do turret e das linhas de ancoragem; em casos extremos, se não houver breakout do turret, as amarras podem tocar os risers submarinos.",
          "trechos": [
            "Eb0ac218822571b86:695:1395",
            "Eb0ac218822571b86:1395:2094"
          ],
          "condicoes": [
            "em evento de perda de controle de thrusters",
            "sob carregamento de vento capaz de alterar o heading da instalação"
          ],
          "limites": [
            "o próprio texto apresenta o contato com risers como caso extremo e condicionado à ausência de turret breakout",
            "não há frequência de ocorrência, critério de prevenção nem consequência quantitativa"
          ]
        }
      ]
    },
    {
      "id": "E87631110ff7acce2",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Regiões de desgaste da linha de ancoragem no mecanismo trumpet do turret não são facilmente inspecionáveis por meios convencionais; a avaliação completa do desgaste tipicamente só é possível após remoção da linha.",
          "trechos": [
            "E87631110ff7acce2:0:696"
          ],
          "condicoes": [
            "aplica-se a linhas de ancoragem que entram no turret spider por mecanismo trumpet"
          ],
          "limites": [
            "o trecho trata de dificuldade de inspeção, não de desempenho estrutural total do sistema",
            "não apresenta taxa de desgaste, vida remanescente nem método universal de aceitação"
          ]
        },
        {
          "proposicao": "Como resposta à limitação de inspeção direta, o exemplo de boa prática descreve uso de modelo preditivo de desgaste atualizado com novas informações, complementado por inspeção limitada com ROV; uso de mergulhadores é cogitado apenas com tempo muito bom e pouco ou nenhum movimento da embarcação.",
          "trechos": [
            "E87631110ff7acce2:0:696",
            "E87631110ff7acce2:696:1395"
          ],
          "condicoes": [
            "quando a inspeção completa da área do trumpet não é possível sem remover a linha",
            "para mergulho, sob condições meteorológicas muito favoráveis e baixo movimento do casco"
          ],
          "limites": [
            "o texto descreve prática de um operador e comparação de boa e má prática, não requisito brasileiro expresso",
            "o ROV é apresentado como inspeção limitada, não solução suficiente em todos os casos"
          ]
        },
        {
          "proposicao": "A orientação destaca a necessidade de saber quais normas foram usadas no equipamento de ancoragem e de manter informação disponível para demonstrar conformidade apropriada, embora o exemplo mencione padrão Class/ISO com aprimoramentos de projeto.",
          "trechos": [
            "E87631110ff7acce2:1395:2085",
            "E87631110ff7acce2:2085:2160"
          ],
          "condicoes": [
            "no contexto de verificação da base normativa e documental do equipamento de ancoragem"
          ],
          "limites": [
            "a referência a Class/ISO aparece no exemplo do guia e não deve ser convertida em requisito normativo brasileiro",
            "o trecho não identifica qual norma específica seria aplicável a todo FPSO"
          ]
        }
      ]
    },
    {
      "id": "E29390a2e1824d7ab",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "O conjunto de dados para treinar e testar a rede neural foi gerado por simulações numéricas, com modelo global em Orcaflex de um FPSO típico com riser flexível operando offshore no Brasil.",
          "trechos": [
            "E29390a2e1824d7ab:0:696"
          ],
          "condicoes": [
            "aplica-se ao estudo descrito",
            "baseado em simulações numéricas e não em dados medidos diretamente em campo"
          ],
          "limites": [
            "a fonte tem independência documental indeterminada e é correlata a achado anterior de conteúdo semelhante, não constituindo estudo independente adicional",
            "o trecho não traz validação de campo nem erro preditivo"
          ]
        },
        {
          "proposicao": "A resposta do FPSO ao carregamento de ondas foi avaliada por operadores de amplitude de resposta em deslocamento, usando diagrama representativo de estados de mar; no estudo foi assumido que todas as ondas vinham da mesma direção.",
          "trechos": [
            "E29390a2e1824d7ab:696:1396"
          ],
          "condicoes": [
            "no arranjo numérico adotado para os estados de mar representativos"
          ],
          "limites": [
            "os intervalos numéricos de Hs e Tp estão apagados e não podem ser reconstruídos",
            "a própria fonte afirma uma hipótese de direção única de ondas no estudo"
          ]
        },
        {
          "proposicao": "A metodologia do estudo encadeia análise global e local: históricos temporais de tração e curvatura obtidos na análise global foram importados para modelo local a fim de calcular tensões nas camadas do riser.",
          "trechos": [
            "E29390a2e1824d7ab:1396:2094"
          ],
          "condicoes": [
            "aplica-se ao método numérico descrito com modelos Orcaflex e HELICA"
          ],
          "limites": [
            "o trecho descreve procedimento de modelagem, não critério geral de projeto ou aceitação",
            "não informa incerteza, calibração nem faixa de validade"
          ]
        }
      ]
    },
